P = [
 dict(pmid='43014643', doi='10.1016/j.envres.2026.126092', journal='Environ Res', title='Exposure-response relationships of outdoor and household air pollution with biomarkers of inflammation and oxidative stress in rural Chinese adults.', short='Rural Beijing solid-fuel cohort 1064 adults outdoor household personal PM2.5 black carbon TNF-alpha IL-6 CRP MDA', design='Prospective cohort', pm='Village outdoor PM2.5 (continuous), household PM2.5 (~30% subsample), 24-h personal PM2.5 and black carbon', geo='China (rural Beijing)', endpoint='Serum IL-6, TNF-alpha, CRP, malondialdehyde', tier='A', basis='Lab / research instrument', affil='McGill University, Canada; University of Chinese Academy of Sciences, China', n='Longitudinal panel of 1,064 adults (mean age 61) in 50 villages over two heating seasons (2018-19, 2019-20), in a region where residential solid fuel dominates PM2.5. Outdoor PM2.5 was monitored continuously per village, household PM2.5 in about 30% of homes, plus 24-h personal PM2.5 and black carbon; models with individual random effects. TNF-alpha rose 1.9% (95% CI 0.2-3.6%) per 10 ug/m3 outdoor PM2.5; no clear association for household or personal exposure, or with IL-6, CRP or MDA. Household exposure was multiply imputed for ~70% of homes, which biases those estimates toward the null, and four biomarkers by four exposures invites one chance hit. Relevance: direct - one of few cohorts with outdoor, indoor and personal PM side by side; the null for measured personal exposure is the result to watch.', sub=corpus.MECH),
 dict(pmid='43014607', doi='10.1016/j.envpol.2026.129480', journal='Environ Pollut', title='Hourly population movement and static-to-dynamic PM2.5 exposure discrepancies in Seoul, South Korea.', short='Seoul 424 dongs hourly PM2.5 surface mobile-network population static vs dynamic exposure discrepancy 2023', design='Machine-learning model', pm='Hourly PM2.5 surface estimates weighted by hourly mobile-network population presence', geo='South Korea (Seoul)', endpoint='Residence-based minus mobility-weighted PM2.5 exposure by hour, neighbourhood type and subgroup', tier='B', basis='Model (CTM / LUR / ML)', affil='State University of New York at Buffalo, USA; Yonsei University, South Korea', n='All 424 Seoul administrative neighbourhoods in 2023: residence-based daily-mean PM2.5 compared with a place-based estimator weighting hourly concentrations by mobile-network population counts. The citywide mean daily discrepancy was modest but systematic: residence weighting underestimated working-hour exposure in activity hubs and evening/overnight exposure in residential neighbourhoods, while mixed-use areas sat near zero. Discrepancies were larger on weekdays and in winter and spring; working-age adults had the largest gaps in hubs, but winter gaps among youth were 25-51% greater. Seasonal variation reflected PM2.5 levels, not population rhythm. Both inputs are modelled surfaces, and indoor time is ignored. Relevance: direct - hourly sensor networks are what make the place-based estimator possible; daily-mean surfaces discard exactly this signal.', sub=corpus.EXPO),
 dict(pmid='43014603', doi='10.1016/j.envpol.2026.129400', journal='Environ Pollut', title='The interplay of urban proximity, environmental exposures and health impacts in Spanish cities.', short='Barcelona Granada Palma Valencia 100 m urban proximity index PM2.5 NO2 NDVI HIA attributable mortality quartiles', design='Health impact model', pm='Gridded PM2.5 and NO2 at 100 m against WHO guideline counterfactual', geo='Spain', endpoint='Premature mortality attributable to non-compliance with WHO air quality and greenness guidelines', tier='B', basis='Model (CTM / LUR / ML)', affil='Yale University, USA; ISGlobal, Spain', n='Four Spanish cities: a 100 m urban proximity index (walkability, cyclability, vitality, 15-minute city) overlaid on PM2.5, NO2, NDVI and population, with grid-level health impact assessment of mortality from non-compliance with WHO guidelines. The most proximate quartile carried the highest burden: PM2.5-attributable mortality 34-102 versus 21-87 per 100,000 in the least proximate, NO2 58-154 versus 20-121, low greenness 21-35 versus 8-17. Ranges span cities; no uncertainty intervals are reported, and applying one concentration-response function across quartiles assumes away the within-city confounding the proximity index carries. Relevance: indirect - central, compact districts are where a 100 m exposure surface most needs dense ground observation to be credible.', sub=corpus.BURD),
 dict(pmid='43014449', doi='10.1016/j.ogla.2026.11.001', journal='Ophthalmol Glaucoma', title='Association of Ambient Air Pollution Exposure With Early Failure After Incisional Glaucoma Surgery.', short='Fudan three-centre 7820 eyes incisional glaucoma surgery early failure PM2.5 PM10 NO2 O3 CO Cox 2015-2025', design='Retrospective cohort', pm='Residential geocoded spatiotemporal PM2.5, PM10, NO2, SO2, O3, CO', geo='China', endpoint='Surgical failure within 30, 60 and 90 days', tier='B', basis='Model (CTM / LUR / ML)', affil='Eye & ENT Hospital, Fudan University, China; Eye & ENT Hospital, Fudan University, China', n='Three tertiary centres, 7,820 eyes after incisional glaucoma surgery (2015-2025), 466 failures by 30 days, 711 by 60 and 1,083 by 90. PM2.5 was associated with failure at every horizon: adjusted HR 1.090 (1.001-1.187) at 30 days, 1.141 (1.064-1.224) at 60 and 1.240 (1.162-1.324) at 90, roughly linear on splines; O3 and CO mattered early, PM10 and NO2 later, SO2 not at all; no between-centre heterogeneity. The abstract does not state the exposure increment or window, and six pollutants across three horizons with subgroup interactions invite multiplicity. Surgical failure has strong clinical determinants (prior surgery, antimetabolite use) only partly captured. Relevance: peripheral - an unusual endpoint; the exposure is a modelled residential surface.', sub=corpus.OTHR),
]
